create table FM_CCY_HOLIDAY (CCY VARCHAR(3) not null  ,HOLIDAY_TYPE VARCHAR(1) null  ,HOLIDAY_DESC VARCHAR(50) null  ,APPLY_IND VARCHAR(1) null  ,HOLIDAY_DATE TIMESTAMP(3) not null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,HUB_BATCH_FLAG VARCHAR(1) null  , primary key(CCY,HOLIDAY_DATE));